      "url": "https://view.inews.qq.com/a/20260806A04Y8T00",
      "kicker": "社会 · 家庭社会学",
      "gist": "苏州一大学生暑假跑外卖，遇电动车没电、找不到地址都找父母兜底，钱没赚到还亏本——\"爱兜底\"的养育方式，正引发对独立能力的反思。",
