      "kicker": "财经 · 经济学",
      "gist": "新华社“十五五”开局之年中国产业发展观察显示，构建以先进制造业为骨干的现代化产业体系被置于突出位置。新一轮十大重点行业稳增长方案推进，《“人工智能+制造”专项行动实施意见》发布，各地引导资源向标志性产业链集聚。上半年我国三次产业齐头并进，实体经济持续巩固壮大，产业体系根基越牢，经济发展的韧性越强。",
