          "lensId": "institutionalism",
          "body": "<b>新制度主义</b>关心目标如何通过制度安排层层落地。从中央“把产业体系摆在第一条”，到地方把资源导向19条标志性产业链，规划之所以有力，是因为它被转化成了考核、要素与政策的真实指挥棒。",
