          "lensId": "econ_behavioral",
          "body": "<b>行为经济学</b>看的不只是“省不省钱”，而是人的真实选择环境：花呗、白条嵌在购物车里“这月买、下月还”，顺手就开通；信用卡的权益却在缩水、年费与分期套路让人犯怵。当“默认选项”从卡片变成App，行为就被悄悄改写——不是年轻人变了，是场景变了。",
