          "body": "<b>工作</b>社会学把劳动看作人与组织之间的契约，而不只是“给钱干活”。当招聘方把“问休息”解读为“好吃懒做”，实质是把员工预设为不计代价的生产单元，只谈创造、不谈福祉。体面的工作，本就包含对休息与边界的基本尊重。",
